DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.refresh_governance_city(text)'::regprocedure) INTO def; def:=replace(def,'severity=LEAST(5,severity+1),governance_delta=governance_delta+1','severity=LEAST(5,severity+p-pi.stage),governance_delta=governance_delta+p-pi.stage'); def:=replace(def,'closing_indicators=(SELECT jsonb_object_agg(indicator,value) FROM public.city_indicators WHERE city_id=_city)','closing_indicators=(SELECT jsonb_object_agg(ci.indicator,COALESCE((SELECT h.after_value FROM public.indicator_history h WHERE h.city_id=_city AND h.indicator=ci.indicator AND h.occurred_at<=m.ends_at ORDER BY h.occurred_at DESC,h.id DESC LIMIT 1),(m.opening_indicators->>ci.indicator)::integer,ci.baseline)) FROM public.city_indicators ci WHERE ci.city_id=_city)'); def:=replace(def,'WHERE mandate_id=m.id AND workflow=''completed''','WHERE mandate_id=m.id AND workflow=''completed'' AND completed_at<=m.ends_at'); def:=replace(def,'WHERE mandate_id=m.id AND workflow=''abandoned''','WHERE mandate_id=m.id AND workflow=''abandoned'' AND completed_at<=m.ends_at'); def:=replace(def,'WHERE mandate_id=m.id AND workflow=''rejected''','WHERE mandate_id=m.id AND workflow=''rejected'' AND voted_at<=m.ends_at'); def:=replace(def,'WHERE mandate_id=m.id AND funded_at IS NOT NULL','WHERE mandate_id=m.id AND funded_at IS NOT NULL AND funded_at<=m.ends_at'); EXECUTE def;END $$;